func main(){db,_:=gorm.Open(sqlite.Open("../../../data/webbuilder.db"),&gorm.Config{});var u models.User;db.First(&u);var p models.Project;db.Where("user_id = ?",u.ID).Order("id DESC").First(&p);sec,_:=os.ReadFile("../../../.jwt-secret");t:=jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.MapClaims{"uid":u.ID,"exp":time.Now().Add(time.Hour).Unix()});tok,_:=t.SignedString([]byte(strings.TrimSpace(string(sec))));base:=fmt.Sprintf("http://127.0.0.1:18082/api/app-api/%d/db",p.ID);call:=func(path string,body any){b,_:=json.Marshal(body);req,_:=http.NewRequest("POST",base+path,bytes.NewReader(b));req.Header.Set("Authorization","Bearer "+tok);req.Header.Set("Content-Type","application/json");r,e:=http.DefaultClient.Do(req);if e!=nil{panic(e)};o,_:=io.ReadAll(r.Body);r.Body.Close();fmt.Printf("%s %d %s\n",path,r.StatusCode,string(o))};call("/query",map[string]any{"sql":"CREATE TABLE IF NOT EXISTS api_test (id SERIAL PRIMARY KEY, name TEXT, status TEXT);","args":[]any{}});call("/insert",map[string]any{"table":"api_test","data":map[string]any{"name":"Alpha","status":"active"}});call("/insert",map[string]any{"table":"api_test","data":map[string]any{"name":"Beta","status":"active"}});call("/select",map[string]any{"table":"api_test","search":"alp","searchFields":[]string{"name"},"page":1,"pageSize":1,"order":"id DESC"});call("/update",map[string]any{"table":"api_test","where":map[string]any{"name":"Alpha"},"data":map[string]any{"status":"done"}});call("/delete",map[string]any{"table":"api_test","where":map[string]any{"name":"Beta"}});call("/query",map[string]any{"sql":"DROP TABLE api_test;","args":[]any{}})}